import re, subprocess, os

files = subprocess.run(['grep','-rln','-e','tasklet_setup','-e','tasklet_init','--include=*.c','drivers/','net/'],
                       capture_output=True, text=True).stdout.split()

interesting = []
for f in files:
    try:
        src = open(f, errors='replace').read()
    except Exception:
        continue
    lines = src.split('\n')
    # find tasklet callback names
    cbs = []
    for i,l in enumerate(lines):
        m = re.search(r'tasklet_(?:init|setup)\s*\(\s*&[^,]+,\s*([A-Za-z_0-9]+)', l)
        if m:
            cbs.append(m.group(1))
    if not cbs:
        continue
    # find plain spin_lock in callback bodies (up to 120 lines after def)
    for cb in set(cbs):
        for i,l in enumerate(lines):
            if re.search(r'\b'+re.escape(cb)+r'\s*\(', l) and not l.strip().startswith('*'):
                # definition or call; find body
                if re.search(r'(static|void|int)\b.*'+re.escape(cb), l) or (i>0 and cb in lines[i-1] and re.search(r'(static|^)', lines[i-1])):
                    pass
            if re.search(r'^[A-Za-z_].*\b'+re.escape(cb)+r'\s*\(', l):
                # candidate definition line
                for j in range(i, min(i+140, len(lines))):
                    if 'spin_lock(' in lines[j].replace('spin_lock_bh','X').replace('spin_lock_irqsave','X').replace('spin_lock_irq','X'):
                        interesting.append((f, cb, i+1, j+1, lines[j].strip()))
                    if j>i and lines[j].startswith('}'):
                        break
                break

for f,cb,i,j,t in interesting:
    print(f"{f}:{i} cb={cb} plain_spin_lock@{j}: {t}")
EOF

